#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

static char ibuf[1 << 16];
static size_t ipos = 0, ilen = 0;
static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof(ibuf), stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return (int)(unsigned char)ibuf[ipos++];
}
static inline ll readLL() {
    int c = gc();
    while (c != -1 && (c < '0' || c > '9')) c = gc();
    ll x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return x;
}

static const int LOG = 17;
static int K;
static vector<int> Pw;
static vector<int> upArr;

// highest ancestor (including c itself) with cell power <= X (monotone along chain)
static inline int topJump(int c, ll X) {
    int cur = c;
    for (int k = LOG - 1; k >= 0; k--) {
        int a = upArr[(size_t)k * K + cur];
        if (a != -1 && (ll)Pw[a] <= X) cur = a;
    }
    return cur;
}

int main() {
    int N = (int)readLL();
    int M = (int)readLL();
    K = N * M;
    Pw.assign((size_t)K, 0);
    for (int i = 0; i < K; i++) Pw[i] = (int)readLL();

    vector<int> ord((size_t)K);
    for (int i = 0; i < K; i++) ord[i] = i;
    sort(ord.begin(), ord.end(), [&](int a, int b) {
        if (Pw[a] != Pw[b]) return Pw[a] < Pw[b];
        return a < b;
    });

    // Kruskal-reconstruction (merge) tree: node of each cell = component right after
    // the cell was processed in ascending power order. Node weight Pw[c], subtree-cell-sum S[c].
    vector<int> dsu((size_t)K, 0), tpar((size_t)K, -1);
    vector<ll> S((size_t)K, 0);
    vector<char> processed((size_t)K, 0);
    int reps[4];

    for (int t = 0; t < K; t++) {
        int c = ord[t];
        int cnt = 0;
        int i = c / M, j = c - i * M;
        for (int d = 0; d < 4; d++) {
            int x;
            if (d == 0) { if (j == 0) continue; x = c - 1; }
            else if (d == 1) { if (j == M - 1) continue; x = c + 1; }
            else if (d == 2) { if (i == 0) continue; x = c - M; }
            else { if (i == N - 1) continue; x = c + M; }
            if (!processed[x]) continue;
            int r = x;
            while (dsu[r] != r) { dsu[r] = dsu[dsu[r]]; r = dsu[r]; }
            bool dup = false;
            for (int q = 0; q < cnt; q++) if (reps[q] == r) { dup = true; break; }
            if (!dup) reps[cnt++] = r;
        }
        processed[c] = true;
        if (cnt == 0) {
            dsu[c] = c;
            S[c] = Pw[c];
        } else {
            ll s = Pw[c];
            for (int q = 0; q < cnt; q++) s += S[reps[q]];
            S[c] = s;
            dsu[c] = c;
            for (int q = 0; q < cnt; q++) {
                tpar[reps[q]] = c;
                dsu[reps[q]] = c;
            }
        }
    }

    upArr.assign((size_t)LOG * K, -1);
    for (int c = 0; c < K; c++) upArr[c] = tpar[c];
    for (int k = 1; k < LOG; k++) {
        int *cur = upArr.data() + (size_t)k * K;
        const int *prv = upArr.data() + (size_t)(k - 1) * K;
        for (int c = 0; c < K; c++) {
            int a = prv[c];
            cur[c] = (a == -1) ? -1 : prv[a];
        }
    }

    // T[c]: final (topmost climbed) node of the flood chain starting at node c with level S[c].
    // next(c) = highest proper ancestor with weight <= S[c]; ancestors are processed later
    // in `ord`, hence computed from top (reverse order).
    vector<int> Tn((size_t)K, 0);
    for (int t = K - 1; t >= 0; t--) {
        int c = ord[t];
        int nxt = topJump(c, S[c]);
        Tn[c] = (nxt == c) ? c : Tn[nxt];
    }

    // Answer for seed s:攀升 to component containing s at level P[s], then follow memoized chain.
    string out;
    out.reserve((size_t)K * 12 + 4);
    char stk[24];
    for (int c = 0; c < K; c++) {
        int n = topJump(c, (ll)Pw[c]);
        ll val = S[Tn[n]];
        int len = 0;
        if (val == 0) out.push_back('0');
        else {
            ll v = val;
            while (v > 0) { stk[len++] = (char)('0' + (int)(v % 10)); v /= 10; }
            while (len > 0) out.push_back(stk[--len]);
        }
        out.push_back((c % M == M - 1) ? '\n' : ' ');
    }
    fwrite(out.data(), 1, out.size(), stdout);
    return 0;
}
